{
  "results": [
    {
      "server": "solo",
      "tools": [
        {
          "tool_name": "solo__identify_session",
          "description": "Identify this session by auto-detection, own solo_process_id/SOLO_PROCESS_ID, or external actor; never use it to target another process.",
          "score": 1.0,
          "input_schema": {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "title": "IdentifySessionParams",
            "type": "object",
            "properties": {
              "pid": {
                "description": "Optional host OS PID fallback (from $$ in shell or os.getpid() in Python). Used only when no explicit identity assertion is provided.",
                "type": "integer",
                "format": "uint32",
                "minimum": 0
              },
              "solo_process_id": {
                "description": "This MCP client's own Solo-managed process ID from SOLO_PROCESS_ID, not a host OS PID and not a timer target.",
                "type": "integer",
                "format": "int64"
              },
              "external": {
                "description": "External actor details for callers that are not Solo-managed processes.",
                "$ref": "#/$defs/IdentifySessionExternalParams"
              }
            },
            "$defs": {
              "IdentifySessionExternalParams": {
                "type": "object",
                "properties": {
                  "agent_id": {
                    "description": "A short identifier for this external actor. Omit to auto-generate from the MCP session ID.",
                    "type": "string"
                  },
                  "name": {
                    "description": "A human-readable display name for this external actor.",
                    "type": "string"
                  },
                  "metadata": {
                    "type": "object",
                    "additionalProperties": true,
                    "default": {}
                  }
                },
                "required": [
                  "name"
                ]
              }
            }
          }
        }
      ]
    }
  ],
